function ErrorNotice({message}:{message:string}) {return message?<p className="mt-5 flex items-start gap-2 rounded-xl border border-red-400/20 bg-red-500/10 p-4 text-sm leading-6 text-red-200" role="alert"><AlertCircle size={18} className="mt-1 shrink-0"/>{message}</p>:null;}
function Steps({step}:{step:number}) {return <ol className="mb-8 flex flex-wrap gap-x-6 gap-y-3 text-xs">{['Upload notes','Choose your challenge','Take the quiz','See your progress'].map((label,i)=><li key={label} aria-current={step===i?'step':undefined} className={`flex items-center gap-2 ${i===step?'text-violet-200':'text-slate-400'}`}><span className={`flex h-6 w-6 items-center justify-center rounded-full ${i<=step?'bg-violet-500/20 text-violet-200':'border border-white/15'}`}>{i<step?<CheckCircle2 size={13}/>:i+1}</span>{label}</li>)}</ol>;}

export function PdfUpload() {
 const router=useRouter(); const [documents,setDocuments]=useState<AiDocument[]>([]);const [configured,setConfigured]=useState<boolean|null>(null);
 const [file,setFile]=useState<File|null>(null);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [loaded,setLoaded]=useState(false);const [dragging,setDragging]=useState(false);
 useEffect(()=>{let active=true;void Promise.all([api<{documents:AiDocument[]}>(aiBase+'/documents'),api<{configured:boolean}>(aiBase+'/status')]).then(([d,s])=>{if(active){setDocuments(d.documents);setConfigured(s.configured);}}).catch(e=>{if(active)setError(errorMessage(e));}).finally(()=>{if(active)setLoaded(true);});return()=>{active=false;};},[]);
 function choose(f:File|undefined){if(!f)return;if(!/\.pdf$/i.test(f.name)||f.size>10*1024*1024){setError('Choose a PDF file up to 10 MB.');return;}setFile(f);setError('');}
 async function upload(e:FormEvent){e.preventDefault();if(!file||busy)return;setBusy(true);setError('');const body=new FormData();body.set('file',file);try{const result=await api<{document:AiDocument}>(aiBase+'/documents',{method:'POST',body});router.push(`${quizBase}/documents/${result.document.id}`);}catch(e){setError(errorMessage(e));}finally{setBusy(false);}}
 return <><PageHeader title="A new way to know what you know." eyebrow="AI PDF Quiz Generator" description="Turn your lecture notes into focused practice. Your PDF. Your pace. Your next breakthrough." action={<Link href={quizBase+'/history'} className="btn-secondary"><History size={17}/>Quiz History</Link>}/><Steps step={0}/>
 {configured===false&&<p className="notice mb-6" role="status">AI generation is not available yet. An administrator needs to configure the backend AI provider. You can still upload and prepare your notes.</p>}
 <div className="grid items-start gap-6 xl:grid-cols-[minmax(0,1fr)_280px]"><form className="panel p-6 md:p-8" onSubmit={upload}><div className="mb-6 flex items-center gap-3"><span className="rounded-xl bg-violet-500/15 p-3 text-violet-300"><FileText size={21}/></span><div><h2 className="text-xl font-semibold">Start with your lecture notes</h2><p className="mt-1 text-sm text-slate-400">Upload a searchable, text-based PDF.</p></div></div>
 <label onDragOver={e=>{e.preventDefault();setDragging(true);}} onDragLeave={()=>setDragging(false)} onDrop={e=>{e.preventDefault();setDragging(false);choose(e.dataTransfer.files[0]);}} className={`relative flex min-h-64 cursor-pointer flex-col items-center justify-center rounded-2xl border-2 border-dashed p-6 text-center transition ${dragging?'border-violet-400 bg-violet-500/15':'border-white/15 bg-slate-900/50 hover:border-violet-400/50'}`}><UploadCloud size={42} className="mb-5 text-violet-300"/><span className="max-w-full break-all text-sm font-medium">{file?file.name:'Drop your PDF here, or browse files'}</span><span className="mt-3 text-xs leading-6 text-slate-400">{file?`${(file.size/1024/1024).toFixed(2)} MB selected`:'PDF only · Up to 10 MB · Maximum 100 pages'}</span><input aria-label="PDF lecture notes" type="file" accept=".pdf,application/pdf" className="mt-5 max-w-full text-xs text-slate-400 file:mr-3 file:rounded-lg file:border-0 file:bg-violet-500/20 file:px-4 file:py-2 file:text-violet-200" onChange={e=>choose(e.target.files?.[0])} disabled={busy}/></label>
 <ErrorNotice message={error}/><div className="mt-6 flex flex-wrap items-center justify-between gap-4"><p className="max-w-sm text-xs leading-6 text-slate-400">Scanned images need OCR first. Protected or damaged PDFs cannot be processed.</p><button className="btn-primary" disabled={!file||busy}>{busy?<LoaderCircle size={17} className="animate-spin"/>:<ArrowRight size={17}/>} {busy?'Reading your PDF…':'Continue to configuration'}</button></div></form>
 <aside className="space-y-5"><Artwork name="quiz" className="aspect-[260/228] rounded-2xl border border-white/10"/><div className="rounded-2xl border border-white/10 bg-slate-900 p-5"><ShieldCheck size={23} className="text-cyan-400"/><h3 className="mt-3 text-sm font-semibold">Your notes stay in your workspace</h3><p className="mt-3 text-xs leading-6 text-slate-400">Only you can access your documents and attempts. When you generate a quiz, extracted text is sent to Gemini. Upload material you have permission to share.</p></div></aside></div>
 <section className="mt-9"><h2 className="section-title mb-5">Your uploaded notes</h2>{!loaded?<p className="text-sm text-slate-400">Loading your documents…</p>:documents.length?<div className="grid gap-4 md:grid-cols-2">{documents.map(d=><Link key={d.id} href={`${quizBase}/documents/${d.id}`} className="panel flex items-center gap-4 p-5 transition hover:border-violet-400/40"><FileText size={25} className="shrink-0 text-violet-300"/><div className="min-w-0"><h3 className="truncate text-sm font-semibold">{d.fileName}</h3><p className="mt-2 text-xs text-slate-400">{d.pages} pages · {formatDate(d.createdAt)}</p></div><ArrowRight size={17} className="ml-auto shrink-0 text-slate-400"/></Link>)}</div>:<EmptyState title="A fresh page" description="Your PDFs will appear here after upload. Reuse them whenever you want another quiz."/>}</section></>;
}

export function QuizConfiguration() {
 const {id}=useParams<{id:string}>();const router=useRouter();const [document,setDocument]=useState<AiDocument|null>(null);const [loaded,setLoaded]=useState(false);const [error,setError]=useState('');const [count,setCount]=useState(10);const [difficulty,setDifficulty]=useState('Medium');const [minutes,setMinutes]=useState(10);const [consent,setConsent]=useState(false);const [busy,setBusy]=useState(false);
 useEffect(()=>{let active=true;void api<{document:AiDocument}>(`${aiBase}/documents/${encodeURIComponent(id)}`).then(d=>{if(active)setDocument(d.document);}).catch(e=>{if(active)setError(errorMessage(e));}).finally(()=>{if(active)setLoaded(true);});return()=>{active=false;};},[id]);
 async function generate(e:FormEvent){e.preventDefault();if(busy||!consent)return;setBusy(true);setError('');try{const {quiz}=await api<{quiz:AiQuiz}>(`${aiBase}/documents/${encodeURIComponent(id)}/generate`,{method:'POST',body:JSON.stringify({questionCount:count,difficulty,durationMinutes:minutes})});router.push(`${quizBase}/quizzes/${quiz.id}`);}catch(e){setError(errorMessage(e));setBusy(false);}}
 if(!loaded)return <LoadingCards/>;
 if(busy)return <><Steps step={1}/><div className="panel mx-auto max-w-2xl px-6 py-14 text-center" role="status"><Artwork name="quiz" className="mx-auto mb-7 aspect-[260/228] w-48 rounded-2xl"/><LoaderCircle className="mx-auto animate-spin text-violet-300" size={30}/><h1 className="mt-5 text-2xl font-semibold">Building your knowledge check…</h1><p className="mx-auto mt-4 max-w-md text-sm leading-7 text-slate-400">Reading the concepts, creating answer choices, and checking that each question is grounded in your notes. This can take up to 90 seconds.</p><p className="mt-5 text-xs text-violet-200">Your quiz timer has not started.</p><Link href={quizBase+'/history'} className="btn-secondary mt-7">Check Quiz History</Link></div></>;
 return <><Link href={quizBase} className="mb-6 inline-flex items-center gap-2 text-sm text-violet-300"><ArrowLeft size={16}/>Your notes</Link><PageHeader title="Make this challenge yours." eyebrow="Quiz configuration" description="Choose the right balance of depth, difficulty, and focus."/><Steps step={1}/>{document?<form className="panel max-w-3xl p-6 md:p-8" onSubmit={generate}><div className="mb-8 flex gap-4 rounded-xl border border-white/10 bg-slate-900/60 p-4"><FileText size={25} className="shrink-0 text-violet-300"/><div className="min-w-0"><h2 className="break-all font-semibold">{document.fileName}</h2><p className="mt-2 text-xs text-slate-400">{document.pages} pages · {document.characters.toLocaleString()} extracted characters</p></div></div>
 <div className="space-y-8"><fieldset><legend className="field-label">How many questions?</legend><div className="mt-2 flex flex-wrap gap-3">{[5,10,20,30].map(n=><button key={n} type="button" onClick={()=>setCount(n)} aria-pressed={count===n} className={count===n?'btn-primary':'btn-secondary'}>{n} questions</button>)}</div></fieldset><fieldset><legend className="field-label">Choose your difficulty</legend><div className="mt-2 grid gap-3 sm:grid-cols-3">{[['Easy','Build your foundation'],['Medium','Connect the concepts'],['Hard','Challenge your understanding']].map(([level,description])=><button type="button" key={level} aria-pressed={difficulty===level} onClick={()=>setDifficulty(level)} className={`rounded-xl border p-4 text-left transition ${difficulty===level?'border-violet-400 bg-violet-500/15':'border-white/15 bg-slate-900'}`}><span className="text-sm font-semibold">{level}</span><span className="mt-2 block text-xs leading-5 text-slate-400">{description}</span></button>)}</div></fieldset><fieldset><legend className="field-label">Time to focus</legend><div className="mt-2 flex flex-wrap gap-3">{[5,10,15,30].map(n=><button key={n} type="button" onClick={()=>setMinutes(n)} aria-pressed={minutes===n} className={minutes===n?'btn-primary':'btn-secondary'}><Clock3 size={16}/>{n} minutes</button>)}</div></fieldset></div>
 <label className="mt-8 flex items-start gap-3 rounded-xl bg-slate-900/70 p-4 text-xs leading-6 text-slate-300"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)} className="mt-1" required/><span>I have permission to use these notes and agree to send the extracted text to Gemini to generate this quiz. AI-generated answers can contain mistakes; verify them against your notes.</span></label><ErrorNotice message={error}/><button className="btn-primary mt-6" disabled={!consent}><Sparkles size={17}/>Generate my quiz<ArrowRight size={17}/></button><p className="mt-4 text-xs text-slate-400">The countdown starts only when you choose Start Quiz.</p></form>:<><ErrorNotice message={error||'Document not found.'}/><Link href={quizBase} className="btn-secondary mt-5">Upload another PDF</Link></>}</>;
}

export function QuizReady(){
 const {id}=useParams<{id:string}>();const router=useRouter();const [quiz,setQuiz]=useState<AiQuiz|null>(null);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const request=useRef<string|null>(null);
 useEffect(()=>{void api<{quiz:AiQuiz}>(`${aiBase}/quizzes/${encodeURIComponent(id)}`).then(d=>setQuiz(d.quiz)).catch(e=>setError(errorMessage(e)));},[id]);
 async function start(){if(busy)return;setBusy(true);setError('');request.current??=crypto.randomUUID();try{const d=await api<AttemptPayload>(`${aiBase}/quizzes/${encodeURIComponent(id)}/attempts`,{method:'POST',body:JSON.stringify({requestId:request.current})});router.push(`${quizBase}/attempts/${d.attempt.id}${d.attempt.status==='submitted'?'/results':''}`);}catch(e){setError(errorMessage(e));setBusy(false);}}
 return <><Steps step={2}/><div className="panel mx-auto max-w-2xl p-7 text-center md:p-10"><Artwork name="quiz" className="mx-auto mb-6 aspect-[260/228] w-44 rounded-xl"/><p className="eyebrow">Your next challenge</p><h1 className="mt-3 break-words text-3xl font-semibold">{quiz?.title||'Your PDF quiz'}</h1>{quiz&&<><div className="mt-6 flex flex-wrap justify-center gap-3"><StatusBadge>{quiz.questionCount} questions</StatusBadge><StatusBadge>{quiz.difficulty}</StatusBadge><StatusBadge>{quiz.durationMinutes} minutes</StatusBadge></div><p className="mx-auto mt-6 max-w-md text-sm leading-7 text-slate-400">Your answers save as you go. The countdown continues if you refresh or leave this page. At the deadline, your saved answers are submitted automatically.</p><button className="btn-primary mt-7" disabled={busy} onClick={start}>{busy?<LoaderCircle size={17} className="animate-spin"/>:<Clock3 size={17}/>}Start Quiz</button><Link className="btn-secondary ml-3 mt-3" href={quizBase+'/history'}>Back to history</Link></>}<ErrorNotice message={error}/></div></>;
}

export function TimedQuiz(){
 const {id}=useParams<{id:string}>();const router=useRouter();const [data,setData]=useState<AttemptPayload|null>(null);const [answers,setAnswers]=useState<(number|null)[]>([]);const [index,setIndex]=useState(0);const [remaining,setRemaining]=useState<number|null>(null);const [error,setError]=useState('');const [pending,setPending]=useState(0);const [busy,setBusy]=useState(false);
 const clock=useRef({seconds:0,at:0});const queue=useRef<Promise<void>>(Promise.resolve());const unsaved=useRef(new Map<number,number>());const submitting=useRef(false);
 useEffect(()=>{let active=true;void api<AttemptPayload>(`${aiBase}/attempts/${encodeURIComponent(id)}`).then(d=>{if(!active)return;if(d.attempt.status==='submitted'){router.replace(`${quizBase}/attempts/${id}/results`);return;}setData(d);setAnswers(d.attempt.answers);const seconds=Math.max(0,(Date.parse(d.attempt.deadline)-Date.parse(d.serverNow))/1000);clock.current={seconds,at:performance.now()};setRemaining(Math.ceil(seconds));}).catch(e=>{if(active)setError(errorMessage(e));});return()=>{active=false;};},[id,router]);
 useEffect(()=>{if(!data)return;const timer=setInterval(()=>setRemaining(Math.max(0,Math.ceil(clock.current.seconds-(performance.now()-clock.current.at)/1000))),250);return()=>clearInterval(timer);},[data]);
 const submit=useCallback(async(automatic=false)=>{
  if(submitting.current)return;submitting.current=true;setBusy(true);
  try{await queue.current;if(!automatic&&unsaved.current.size)throw new Error('Some answers have not saved. Retry saving before submitting.');await api(`${aiBase}/attempts/${encodeURIComponent(id)}/submit`,{method:'POST',body:'{}'});router.replace(`${quizBase}/attempts/${id}/results`);}
  catch(e){setError(errorMessage(e));}finally{submitting.current=false;setBusy(false);}
 },[id,router]);
 useEffect(()=>{if(remaining!==0||!data)return;void submit(true);const retry=setInterval(()=>void submit(true),5000);return()=>clearInterval(retry);},[remaining,data,submit]);
 function save(questionIndex:number,answer:number){
  setAnswers(prev=>prev.map((a,i)=>i===questionIndex?answer:a));unsaved.current.set(questionIndex,answer);setPending(unsaved.current.size);setError('');
  queue.current=queue.current.then(async()=>{try{await api(`${aiBase}/attempts/${encodeURIComponent(id)}/answers`,{method:'PATCH',body:JSON.stringify({questionIndex,answer})});if(unsaved.current.get(questionIndex)===answer)unsaved.current.delete(questionIndex);setPending(unsaved.current.size);}catch(e){setError(errorMessage(e));if(e instanceof ApiError&&e.status===409)void submit(true);}});
 }
 if(!data)return <><LoadingCards/><ErrorNotice message={error}/></>;
 const question=data.questions[index];const answered=answers.filter(a=>a!==null).length;const ended=remaining===0||busy;
 return <><div className="mb-6 flex flex-wrap items-start justify-between gap-4"><div><p className="eyebrow">Your focus session</p><h1 className="mt-2 text-2xl font-semibold">{data.quiz.title}</h1><p className="mt-2 text-xs text-slate-400">{data.quiz.difficulty} · {data.questions.length} questions</p></div><div className={`rounded-xl border px-5 py-3 ${remaining!==null&&remaining<=60?'border-red-400/40 bg-red-500/10 text-red-200':'border-violet-400/30 bg-violet-500/10 text-violet-200'}`}><span className="flex items-center gap-2 text-xs"><Clock3 size={15}/>Time remaining</span><p role="timer" aria-label="Time remaining" className="mt-1 text-right font-mono text-2xl font-semibold tabular-nums">{clockTime(remaining??0)}</p></div></div>
 <div className="grid items-start gap-6 xl:grid-cols-[minmax(0,1fr)_230px]"><section className="panel p-5 sm:p-8"><ProgressBar value={answered/data.questions.length*100} label={`Question ${index+1} of ${data.questions.length}`}/><fieldset disabled={ended} className="mt-8"><legend className="text-xl font-semibold leading-8">{question.question}</legend><div className="mt-6 space-y-3">{question.options.map((option,i)=><label key={i} className="quiz-option" data-selected={answers[index]===i}><input type="radio" className="mt-1" name={`ai-question-${index}`} checked={answers[index]===i} onChange={()=>save(index,i)}/><span className="font-semibold text-violet-300">{String.fromCharCode(65+i)}.</span><span>{option}</span></label>)}</div></fieldset><ErrorNotice message={error}/>{pending>0&&error&&<button className="btn-secondary mt-4" disabled={ended} onClick={()=>{for(const [i,a]of unsaved.current)save(i,a);}}><RefreshCw size={15}/>Retry saving answers</button>}
 <div className="mt-8 flex flex-wrap justify-between gap-3"><button className="btn-secondary" disabled={index===0} onClick={()=>setIndex(i=>i-1)}><ArrowLeft size={16}/>Previous</button><button className="btn-primary" disabled={index===data.questions.length-1} onClick={()=>setIndex(i=>i+1)}>Next<ArrowRight size={16}/></button></div><p className="mt-5 text-xs text-slate-400" role="status">{remaining===0?'Time is up. Submitting your saved answers…':pending?`${pending} answer(s) waiting to save. Keep this page open.`:'All answers saved. You can safely refresh.'}</p></section>
 <aside className="panel p-5"><h2 className="text-sm font-semibold">Your questions</h2><div className="mt-4 grid grid-cols-5 gap-2">{data.questions.map((_,i)=><button key={i} onClick={()=>setIndex(i)} aria-label={`Question ${i+1}${answers[i]!==null?', answered':''}`} aria-current={index===i?'step':undefined} className={`h-9 rounded-lg text-xs font-semibold transition ${index===i?'bg-violet-500 text-white':answers[i]!==null?'border border-violet-400/40 bg-violet-500/15 text-violet-200':'border border-white/10 bg-slate-900 text-slate-400'}`}>{i+1}</button>)}</div><p className="mt-5 text-xs text-slate-400">{answered} of {data.questions.length} answered</p><button className="btn-primary mt-5 w-full" disabled={ended||pending>0} onClick={()=>{if(answered<data.questions.length&&!window.confirm(`Submit with ${data.questions.length-answered} unanswered question(s)?`))return;void submit();}}><Send size={16}/>{busy?'Submitting…':'Submit quiz'}</button><p className="mt-4 text-xs leading-6 text-slate-400">Unanswered questions receive no marks. Your saved answers are final when submitted.</p></aside></div></>;
}

export function QuizResults(){
 const {id}=useParams<{id:string}>();const [data,setData]=useState<AttemptPayload|null>(null);const [error,setError]=useState('');
 useEffect(()=>{void api<AttemptPayload>(`${aiBase}/attempts/${encodeURIComponent(id)}`).then(setData).catch(e=>setError(errorMessage(e)));},[id]);
 if(!data)return <><LoadingCards/><ErrorNotice message={error}/></>;
 const a=data.attempt;
 if(a.status!=='submitted')return <EmptyState title="Your quiz is still in progress" description="Submit the quiz or wait for the countdown to finish to see your results." href={`${quizBase}/attempts/${id}`} action="Resume quiz"/>;
 return <><Steps step={3}/><div className="workspace-welcome flex flex-wrap items-center justify-between gap-5"><div><p className="eyebrow">Another step forward</p><h1 className="mt-3 text-3xl font-bold">Your quiz results</h1><p className="mt-3 break-words text-sm text-slate-300">{data.quiz.title} · {data.quiz.difficulty}</p><p className="mt-3 text-xs text-slate-400">{a.timedOut?'Time ended — your saved answers were submitted automatically.':'Submitted successfully.'} Time taken: {clockTime(a.timeTakenSeconds??0)}</p></div><div className="rounded-2xl border border-violet-400/30 bg-slate-900/60 px-8 py-6 text-center"><p className="gradient-text text-5xl font-bold">{a.percentage}%</p><p className="mt-3 text-sm text-slate-300">{a.correct} / {a.total} points</p></div></div>
 <div className="mb-8 grid gap-4 sm:grid-cols-3"><DashboardCard label="Correct answers" value={a.correct??0} icon={CheckCircle2}/><DashboardCard label="Incorrect answers" value={a.incorrect??0} icon={AlertCircle}/><DashboardCard label="Unanswered" value={a.unanswered??0} icon={FileText}/></div><div className="mb-9 flex flex-wrap gap-3"><Link className="btn-primary" href={`${quizBase}/quizzes/${data.quiz.id}`}><RefreshCw size={16}/>Retake quiz</Link><Link className="btn-secondary" href={`${quizBase}/documents/${data.quiz.documentId}`}><Sparkles size={16}/>New quiz from this PDF</Link><Link className="btn-secondary" href={quizBase+'/history'}><History size={16}/>Quiz History</Link></div>
 <h2 className="section-title mb-5">Understand every answer</h2><p className="mb-6 text-xs leading-6 text-slate-400">AI-generated explanations may contain errors. Use the source quote to check each answer against your lecture notes.</p><div className="space-y-5">{data.questions.map((q,i)=>{const selected=a.answers[i];const correct=selected===q.answer;return <article key={i} className="panel p-5 sm:p-7"><div className="mb-4 flex items-center justify-between gap-3"><p className="eyebrow">Question {i+1}</p><StatusBadge tone={correct?'green':selected===null?'amber':'red'}>{correct?'Correct':selected===null?'Unanswered':'Incorrect'}</StatusBadge></div><h3 className="font-semibold leading-7">{q.question}</h3><div className="mt-4 grid gap-2 sm:grid-cols-2">{q.options.map((option,j)=><p key={j} className={`rounded-xl border p-3 text-sm leading-6 ${j===q.answer?'border-emerald-400/30 bg-emerald-500/10 text-emerald-200':j===selected?'border-red-400/30 bg-red-500/10 text-red-200':'border-white/10 text-slate-400'}`}><span className="mr-2 font-semibold">{String.fromCharCode(65+j)}.</span>{option}{j===q.answer?' ✓':''}{j===selected?' · Your answer':''}</p>)}</div><p className="mt-5 text-sm leading-7 text-slate-300">{q.explanation}</p><blockquote className="mt-4 border-l-2 border-violet-400/50 pl-4 text-xs italic leading-6 text-slate-400">From your notes: “{q.sourceQuote}”</blockquote></article>;})}</div></>;
}

export function QuizHistory(){
 const [attempts,setAttempts]=useState<AiAttempt[]>([]);const [quizzes,setQuizzes]=useState<AiQuiz[]>([]);const [page,setPage]=useState(1);const [total,setTotal]=useState(0);const [loaded,setLoaded]=useState(false);const [error,setError]=useState('');
 useEffect(()=>{let active=true;void api<{attempts:AiAttempt[];quizzes:AiQuiz[];total:number}>(`${aiBase}/history?page=${page}`).then(d=>{if(active){setAttempts(d.attempts);setQuizzes(d.quizzes);setTotal(d.total);}}).catch(e=>{if(active)setError(errorMessage(e));}).finally(()=>{if(active)setLoaded(true);});return()=>{active=false;};},[page]);
 return <><PageHeader title="Every attempt is progress." eyebrow="AI quiz history" description="Pick up a quiz, revisit an explanation, or give a familiar topic another try." action={<Link href={quizBase} className="btn-primary"><UploadCloud size={17}/>Upload notes</Link>}/><ErrorNotice message={error}/>{!loaded?<LoadingCards/>:attempts.length?<><div className="table-wrap"><table className="data-table"><thead><tr><th>Quiz</th><th>Started</th><th>Status</th><th>Score</th><th>Time taken</th><th>Action</th></tr></thead><tbody>{attempts.map(a=>{const q=quizzes.find(q=>q.id===a.quizId);return <tr key={a.id}><td><p className="max-w-60 truncate font-medium">{q?.title??'PDF quiz'}</p><p className="mt-1 text-xs text-slate-400">{q?`${q.questionCount} questions · ${q.difficulty}`:''}</p></td><td className="whitespace-nowrap">{formatDate(a.startedAt)}</td><td><StatusBadge tone={a.status==='submitted'?'green':'amber'}>{a.status==='submitted'?'Completed':'In progress'}</StatusBadge></td><td>{a.percentage!==undefined?`${a.percentage}%`:'—'}</td><td>{a.timeTakenSeconds!==undefined?clockTime(a.timeTakenSeconds):'—'}</td><td><Link className="text-sm font-medium text-violet-300" href={`${quizBase}/attempts/${a.id}${a.status==='submitted'?'/results':''}`}>{a.status==='submitted'?'Review results':'Resume quiz'}</Link></td></tr>;})}</tbody></table></div><div className="mt-5 flex items-center justify-between gap-3 text-sm"><button className="btn-secondary" disabled={page===1} onClick={()=>setPage(p=>p-1)}>Previous</button><p className="text-slate-400">Page {page} · {total} attempts</p><button className="btn-secondary" disabled={page*20>=total} onClick={()=>setPage(p=>p+1)}>Next</button></div></>:<EmptyState title="Your story starts with one attempt" description="Generate a quiz from your lecture notes to start building your history." href={quizBase} action="Create a PDF quiz"/>}
 {quizzes.length>0&&<section className="mt-10"><h2 className="section-title mb-5">Your generated quizzes</h2><div className="grid gap-4 md:grid-cols-2">{quizzes.map(q=><div className="panel p-5" key={q.id}><h3 className="truncate font-semibold">{q.title}</h3><p className="mt-3 text-xs text-slate-400">{q.questionCount} questions · {q.difficulty} · {q.durationMinutes} min</p><div className="mt-5 flex flex-wrap gap-3"><Link className="btn-secondary" href={`${quizBase}/quizzes/${q.id}`}>Open quiz<ArrowRight size={15}/></Link><Link className="inline-flex items-center gap-1 text-xs text-violet-300" href={`${quizBase}/documents/${q.documentId}`}><Sparkles size={14}/>Generate another</Link></div></div>)}</div></section>}</>;
}
